insert into public.question_assets (id, description, bible_reference, generation_prompt, ownership, license, is_artistic_interpretation, interpretation_note, alt_text, storage_path, width, height, review_status) values ('hero_jerusalem','Ancient Jerusalem at sunrise from the Mount of Olives','Psalm 125:2 (setting)','Wide panoramic view of ancient Jerusalem at sunrise seen from the Mount of Olives, limestone walls and the Second Temple glowing gold, olive trees, a lone traveler with a staff. Cinematic, painterly realism in the tradition of classical biblical oil paintings with modern film lighting; ancient Near Eastern setting, historically plausible clothing and architecture; warm golden-hour light with deep navy shadows; palette of deep navy, antique gold, ivory, emerald and subtle amethyst; dignified adult tone; no text or logos.','MyBibleGem project owner','AI-generated for MyBibleGem (GPT Image); confirm commercial-use terms of the generator before release',true,'Artistic reconstruction of Second Temple-era Jerusalem; architecture is approximate, not an archaeological model.','Ancient Jerusalem glowing gold at sunrise, seen from an olive grove with a traveller on the path.','/images/hero_jerusalem.webp',1200,675,'review') on conflict (id) do nothing;
insert into public.question_assets (id, description, bible_reference, generation_prompt, ownership, license, is_artistic_interpretation, interpretation_note, alt_text, storage_path, width, height, review_status) values ('creation','Light breaking over the primordial waters','Genesis 1:1-5','The creation of the world: light breaking across dark primordial waters as dry land, plants, sun, moon and stars appear; the world is newly made, with no buildings, ruins, people or human-made objects anywhere. Cinematic, painterly realism in the tradition of classical biblical oil paintings with modern film lighting; untouched natural world with no architecture; warm golden-hour light with deep navy shadows; palette of deep navy, antique gold, ivory, emerald and subtle amethyst; dignified adult tone; no text or logos.','MyBibleGem project owner','AI-generated for MyBibleGem (GPT Image); confirm commercial-use terms of the generator before release',true,'Artistic interpretation. Faces, clothing, colours and composition are imagined; only the event itself is described in Scripture.','Rays of light breaking over dark waters as land and plants emerge.','/images/creation.webp',1200,900,'review') on conflict (id) do nothing;
