insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('pic-solomon_temple-4','picture',11,7,21,21,'1 Kings 7:21',4,'What names were given to the two bronze pillars of Solomon''s temple porch?',null,'["Urim and Thummim", "Jachin and Boaz", "Shem and Japheth", "Ebal and Gerizim"]'::jsonb,1,'The right pillar was called Jachin and the left pillar Boaz.','Read 1 Kings 7:21.','solomon_temple','A king in royal robes before a grand temple with bronze pillars as offerings smoke.','KJV',array['solomon_temple','1 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And he set up the pillars in the porch of the temple: and he set up the right pillar, and called the name thereof Jachin: and he set up the left pillar, and called the name thereof Boaz.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('pic-solomon_temple-5','picture',11,5,6,6,'1 Kings 5:6',3,'What trees did Solomon ask Hiram''s servants to cut from Lebanon?',null,'["Cedar trees", "Palm trees", "Sycamore trees", "Olive trees"]'::jsonb,0,'Solomon asked Hiram to "hew me cedar trees out of Lebanon." (Hiram also supplied fir.)','Read 1 Kings 5:6.','solomon_temple','A king in royal robes before a grand temple with bronze pillars as offerings smoke.','KJV',array['solomon_temple','1 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Now therefore command thou that they hew me cedar trees out of Lebanon; and my servants shall be with thy servants: and unto thee will I give hire for thy servants according to all that thou shalt appoint: for thou knowest that there is not among us any that can skill to hew timber like unto the Sidonians.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('pic-elijah_carmel-1','picture',11,18,36,38,'1 Kings 18:36-38',1,'Which prophet saw fire fall from heaven on Mount Carmel?',null,'["Elisha", "Isaiah", "Jeremiah", "Elijah"]'::jsonb,3,'After Elijah prayed, the fire of the LORD fell and consumed the burnt sacrifice.','Read 1 Kings 18:36-38.','elijah_carmel','Fire falls from a stormy sky onto a stone altar while a prophet stands beside it.','KJV',array['elijah_carmel','1 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And it came to pass at the time of the offering of the evening sacrifice, that Elijah the prophet came near, and said, LORD God of Abraham, Isaac, and of Israel, let it be known this day that thou art God in Israel, and that I am thy servant, and that I have done all these things at thy word. Hear me, O LORD, hear me, that this people may know that thou art the LORD God, and that thou hast turned their heart back again. Then the fire of the LORD fell, and consumed the burnt sacrifice, and the wood, and the stones, and the dust, and licked up the water that was in the trench.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('pic-elijah_carmel-2','picture',11,18,19,19,'1 Kings 18:19',1,'Prophets of which god opposed Elijah on Mount Carmel?',null,'["Dagon", "Chemosh", "Molech", "Baal"]'::jsonb,3,'Elijah asked Ahab to gather the prophets of Baal to Mount Carmel.','Read 1 Kings 18:19.','elijah_carmel','Fire falls from a stormy sky onto a stone altar while a prophet stands beside it.','KJV',array['elijah_carmel','1 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Now therefore send, and gather to me all Israel unto mount Carmel, and the prophets of Baal four hundred and fifty, and the prophets of the groves four hundred, which eat at Jezebel’s table.') on conflict (id) do nothing;
