insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('pic-elijah_carmel-4','picture',11,18,43,44,'1 Kings 18:43-44',4,'How many times did Elijah send his servant to look toward the sea before a cloud appeared?',null,'["Forty", "Twelve", "Seven", "Three"]'::jsonb,2,'On the seventh time the servant saw a little cloud like a man''s hand.','Read 1 Kings 18:43-44.','elijah_carmel','Fire falls from a stormy sky onto a stone altar while a prophet stands beside it.','KJV',array['elijah_carmel','1 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And said to his servant, Go up now, look toward the sea. And he went up, and looked, and said, There is nothing. And he said, Go again seven times. And it came to pass at the seventh time, that he said, Behold, there ariseth a little cloud out of the sea, like a man’s hand. And he said, Go up, say unto Ahab, Prepare thy chariot, and get thee down, that the rain stop thee not.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('pic-elijah_carmel-5','picture',11,18,39,39,'1 Kings 18:39',2,'When the fire fell on Mount Carmel, what did the people cry out?',null,'["Hosanna in the highest", "God save the king", "The LORD, he is the God", "Great is our god Baal"]'::jsonb,2,'The people fell on their faces and said, "The LORD, he is the God; the LORD, he is the God."','Read 1 Kings 18:39.','elijah_carmel','Fire falls from a stormy sky onto a stone altar while a prophet stands beside it.','KJV',array['elijah_carmel','1 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And when all the people saw it, they fell on their faces: and they said, The LORD, he is the God; the LORD, he is the God.') on conflict (id) do nothing;
