insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('pic-daniel_lions-3','picture',27,6,10,10,'Daniel 6:10',2,'How many times a day did Daniel kneel to pray?',null,'["Three", "Seven", "Two", "Once"]'::jsonb,0,'Daniel kneeled upon his knees three times a day and prayed.','Read Daniel 6:10.','daniel_lions','A calm man in robes stands among resting lions in a dim stone den.','KJV',array['daniel_lions','Daniel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Now when Daniel knew that the writing was signed, he went into his house; and his windows being open in his chamber toward Jerusalem, he kneeled upon his knees three times a day, and prayed, and gave thanks before his God, as he did aforetime.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('pic-daniel_lions-4','picture',27,6,22,22,'Daniel 6:22',2,'According to Daniel, how was he protected from the lions?',null,'["The king''s guards stood watch", "He hid in a cave", "The lions were already fed", "God sent His angel and shut their mouths"]'::jsonb,3,'Daniel said, "My God hath sent his angel, and hath shut the lions'' mouths."','Read Daniel 6:22.','daniel_lions','A calm man in robes stands among resting lions in a dim stone den.','KJV',array['daniel_lions','Daniel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'My God hath sent his angel, and hath shut the lions’ mouths, that they have not hurt me: forasmuch as before him innocency was found in me; and also before thee, O king, have I done no hurt.') on conflict (id) do nothing;
