insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('pic-solomon_temple-8','picture',11,5,8,10,'1 Kings 5:8-10',2,'Which king of Tyre sent cedar and fir timber for the temple?',null,'["Hiram", "Cyrus", "Nebuchadnezzar", "Ahab"]'::jsonb,0,'Hiram gave Solomon cedar trees and fir trees according to all his desire.','Read 1 Kings 5:8-10.','solomon_temple','A king in royal robes before a grand temple with bronze pillars as offerings smoke.','KJV',array['solomon_temple','1 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And Hiram sent to Solomon, saying, I have considered the things which thou sentest to me for: and I will do all thy desire concerning timber of cedar, and concerning timber of fir. My servants shall bring them down from Lebanon unto the sea: and I will convey them by sea in floats unto the place that thou shalt appoint me, and will cause them to be discharged there, and thou shalt receive them: and thou shalt accomplish my desire, in giving food for my household. So Hiram gave Solomon cedar trees and fir trees according to all his desire.') on conflict (id) do nothing;
