insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('pic-elijah_carmel-7','picture',11,18,33,35,'1 Kings 18:33-35',3,'What did Elijah have poured over the sacrifice on Mount Carmel?',null,'["Wine", "Oil", "Water", "Blood"]'::jsonb,2,'Barrels of water were poured on the sacrifice three times until the trench was filled.','Read 1 Kings 18:33-35.','elijah_carmel','Fire falls from a stormy sky onto a stone altar while a prophet stands beside it.','KJV',array['elijah_carmel','1 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And he put the wood in order, and cut the bullock in pieces, and laid him on the wood, and said, Fill four barrels with water, and pour it on the burnt sacrifice, and on the wood. And he said, Do it the second time. And they did it the second time. And he said, Do it the third time. And they did it the third time. And the water ran round about the altar; and he filled the trench also with water.') on conflict (id) do nothing;
