insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('pic-daniel_lions-6','picture',27,6,13,13,'Daniel 6:13',2,'Why was Daniel cast into the den of lions?',null,'["He refused the king''s meat", "He kept praying to his God despite the king''s decree", "He would not bow to a golden image", "He read the writing on the wall"]'::jsonb,1,'His accusers said Daniel regarded not the king''s decree but made his petition three times a day.','Read Daniel 6:13.','daniel_lions','A calm man in robes stands among resting lions in a dim stone den.','KJV',array['daniel_lions','Daniel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Then answered they and said before the king, That Daniel, which is of the children of the captivity of Judah, regardeth not thee, O king, nor the decree that thou hast signed, but maketh his petition three times a day.') on conflict (id) do nothing;
