insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('pic-empty_tomb-7','picture',43,20,2,4,'John 20:2-4',3,'Who ran with Peter to the tomb and got there first?',null,'["Thomas", "James", "Andrew", "The other disciple, whom Jesus loved"]'::jsonb,3,'The other disciple, whom Jesus loved, did outrun Peter and came first to the sepulchre.','Read John 20:2-4.','empty_tomb','Women carrying spices approach a rock-cut tomb whose stone has been rolled away.','KJV',array['empty_tomb','John']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Then she runneth, and cometh to Simon Peter, and to the other disciple, whom Jesus loved, and saith unto them, They have taken away the Lord out of the sepulchre, and we know not where they have laid him. Peter therefore went forth, and that other disciple, and came to the sepulchre. So they ran both together: and the other disciple did outrun Peter, and came first to the sepulchre.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-noah','whoami',1,6,13,14,'Genesis 6:13-14',1,'Who am I?','["I lived before a great flood.", "God told me to build with gopher wood.", "My sons were Shem, Ham and Japheth.", "I built the ark."]'::jsonb,'["Abraham", "Enoch", "Lot", "Noah"]'::jsonb,3,'God told Noah, "Make thee an ark of gopher wood."','Look in Genesis.',null,null,'KJV',array['noah','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And God said unto Noah, The end of all flesh is come before me; for the earth is filled with violence through them; and, behold, I will destroy them with the earth. Make thee an ark of gopher wood; rooms shalt thou make in the ark, and shalt pitch it within and without with pitch.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-moses','whoami',2,3,2,4,'Exodus 3:2-4',1,'Who am I?','["As a baby I was hidden in an ark of bulrushes.", "I was raised in Pharaoh''s household.", "I saw a bush burn without being consumed.", "I led Israel out of Egypt."]'::jsonb,'["Moses", "Aaron", "Joseph", "Joshua"]'::jsonb,0,'God called to Moses out of the midst of the burning bush.','Look in Exodus.',null,null,'KJV',array['moses','Exodus']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And the angel of the LORD appeared unto him in a flame of fire out of the midst of a bush: and he looked, and, behold, the bush burned with fire, and the bush was not consumed. And Moses said, I will now turn aside, and see this great sight, why the bush is not burnt. And when the LORD saw that he turned aside to see, God called unto him out of the midst of the bush, and said, Moses, Moses. And he said, Here am I.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-ruth','whoami',8,1,16,16,'Ruth 1:16',2,'Who am I?','["I was a woman of Moab.", "I told my mother-in-law: whither thou goest, I will go.", "I gleaned in the fields of Boaz.", "I became an ancestor of King David."]'::jsonb,'["Naomi", "Ruth", "Rahab", "Orpah"]'::jsonb,1,'Ruth said to Naomi, "Whither thou goest, I will go."','Look in the books of history.',null,null,'KJV',array['ruth','Ruth']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And Ruth said, Intreat me not to leave thee, or to return from following after thee: for whither thou goest, I will go; and where thou lodgest, I will lodge: thy people shall be my people, and thy God my God:') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-samuel','whoami',9,3,10,10,'1 Samuel 3:10',2,'Who am I?','["My mother Hannah prayed for me at Shiloh.", "As a boy I served Eli the priest.", "I heard the LORD call my name in the night.", "I anointed both Saul and David."]'::jsonb,'["Nathan", "Eli", "Gad", "Samuel"]'::jsonb,3,'The LORD came and called, "Samuel, Samuel."','Look in the books of history.',null,null,'KJV',array['samuel','1 Samuel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And the LORD came, and stood, and called as at other times, Samuel, Samuel. Then Samuel answered, Speak; for thy servant heareth.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-samson','whoami',7,16,30,30,'Judges 16:30',1,'Who am I?','["I was a Nazarite from birth.", "I tore a young lion with my bare hands.", "Delilah learned the secret of my strength.", "I pulled down the house where the Philistines gathered."]'::jsonb,'["Samson", "Gideon", "Saul", "Jephthah"]'::jsonb,0,'Samson bowed himself with all his might and the house fell.','Look in Judges.',null,null,'KJV',array['samson','Judges']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And Samson said, Let me die with the Philistines. And he bowed himself with all his might; and the house fell upon the lords, and upon all the people that were therein. So the dead which he slew at his death were more than they which he slew in his life.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-gideon','whoami',7,7,7,7,'Judges 7:7',3,'Who am I?','["An angel found me threshing wheat by a winepress.", "I tested God with a fleece.", "My army was reduced to three hundred men.", "We carried trumpets, pitchers and lamps."]'::jsonb,'["Joshua", "Gideon", "Barak", "Ehud"]'::jsonb,1,'The LORD said to Gideon, "By the three hundred men... will I save you."','Look in Judges.',null,null,'KJV',array['gideon','Judges']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And the LORD said unto Gideon, By the three hundred men that lapped will I save you, and deliver the Midianites into thine hand: and let all the other people go every man unto his place.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-deborah','whoami',7,4,4,5,'Judges 4:4-5',3,'Who am I?','["I was a prophetess.", "I judged Israel under a palm tree in mount Ephraim.", "I summoned Barak to fight Sisera.", "A song of mine is recorded in Judges 5."]'::jsonb,'["Miriam", "Jael", "Huldah", "Deborah"]'::jsonb,3,'Deborah judged Israel and dwelt under the palm tree of Deborah.','Look in Judges.',null,null,'KJV',array['deborah','Judges']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And Deborah, a prophetess, the wife of Lapidoth, she judged Israel at that time. And she dwelt under the palm tree of Deborah between Ramah and Beth-el in mount Ephraim: and the children of Israel came up to her for judgment.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-elisha','whoami',12,2,9,9,'2 Kings 2:9',3,'Who am I?','["I was ploughing with twelve yoke of oxen when I was called.", "I asked for a double portion of my master''s spirit.", "I took up the mantle that fell from Elijah.", "I told Naaman to wash in the Jordan seven times."]'::jsonb,'["Obadiah", "Gehazi", "Elijah", "Elisha"]'::jsonb,3,'Elisha said, "Let a double portion of thy spirit be upon me."','Look in 2 Kings.',null,null,'KJV',array['elisha','2 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And it came to pass, when they were gone over, that Elijah said unto Elisha, Ask what I shall do for thee, before I be taken away from thee. And Elisha said, I pray thee, let a double portion of thy spirit be upon me.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-joseph','whoami',1,41,41,41,'Genesis 41:41',1,'Who am I?','["I was my father''s favourite son.", "My brothers sold me into slavery.", "I interpreted Pharaoh''s dreams.", "I was set over all the land of Egypt."]'::jsonb,'["Moses", "Judah", "Joseph", "Benjamin"]'::jsonb,2,'Pharaoh said to Joseph, "I have set thee over all the land of Egypt."','Look in Genesis.',null,null,'KJV',array['joseph','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And Pharaoh said unto Joseph, See, I have set thee over all the land of Egypt.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-abraham','whoami',1,22,1,2,'Genesis 22:1-2',1,'Who am I?','["I left Ur of the Chaldees.", "God changed my name.", "My wife laughed at God''s promise of a son.", "God tested me in the land of Moriah."]'::jsonb,'["Abraham", "Isaac", "Jacob", "Lot"]'::jsonb,0,'God tempted (tested) Abraham and sent him to the land of Moriah.','Look in Genesis.',null,null,'KJV',array['abraham','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And it came to pass after these things, that God did tempt Abraham, and said unto him, Abraham: and he said, Behold, here I am. And he said, Take now thy son, thine only son Isaac, whom thou lovest, and get thee into the land of Moriah; and offer him there for a burnt offering upon one of the mountains which I will tell thee of.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-jacob','whoami',1,32,28,28,'Genesis 32:28',1,'Who am I?','["I was born holding my twin brother''s heel.", "I bought my brother''s birthright with pottage.", "I dreamed of a ladder reaching to heaven.", "God renamed me Israel."]'::jsonb,'["Isaac", "Laban", "Jacob", "Esau"]'::jsonb,2,'"Thy name shall be called no more Jacob, but Israel."','Look in Genesis.',null,null,'KJV',array['jacob','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And he said, Thy name shall be called no more Jacob, but Israel: for as a prince hast thou power with God and with men, and hast prevailed.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-esau','whoami',1,25,30,33,'Genesis 25:30-33',2,'Who am I?','["I was a cunning hunter.", "I was born red and hairy.", "I sold my birthright for a meal.", "I am also called Edom."]'::jsonb,'["Ishmael", "Nimrod", "Jacob", "Esau"]'::jsonb,3,'Esau sold his birthright unto Jacob.','Look in Genesis.',null,null,'KJV',array['esau','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And Esau said to Jacob, Feed me, I pray thee, with that same red pottage; for I am faint: therefore was his name called Edom. And Jacob said, Sell me this day thy birthright. And Esau said, Behold, I am at the point to die: and what profit shall this birthright do to me? And Jacob said, Swear to me this day; and he sware unto him: and he sold his birthright unto Jacob.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-joshua','whoami',6,24,15,15,'Joshua 24:15',1,'Who am I?','["I was one of twelve men sent to spy out Canaan.", "I succeeded Moses as leader.", "The walls of Jericho fell when the people shouted.", "I said: As for me and my house, we will serve the LORD."]'::jsonb,'["Joshua", "Caleb", "Gideon", "Aaron"]'::jsonb,0,'Joshua 24:15: "As for me and my house, we will serve the LORD."','Look in the books of history.',null,null,'KJV',array['joshua','Joshua']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And if it seem evil unto you to serve the LORD, choose you this day whom ye will serve; whether the gods which your fathers served that were on the other side of the flood, or the gods of the Amorites, in whose land ye dwell: but as for me and my house, we will serve the LORD.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-rahab','whoami',6,2,1,18,'Joshua 2:1-18',2,'Who am I?','["My house was upon the town wall of Jericho.", "I hid two Israelite spies.", "I let them down by a cord through a window.", "A line of scarlet thread marked my home."]'::jsonb,'["Rahab", "Jael", "Deborah", "Ruth"]'::jsonb,0,'The spies told Rahab to bind the scarlet thread in the window.','Look in Joshua.',null,null,'KJV',array['rahab','Joshua']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And Joshua the son of Nun sent out of Shittim two men to spy secretly, saying, Go view the land, even Jericho. And they went, and came into an harlot’s house, named Rahab, and lodged there. And it was told the king of Jericho, saying, Behold, there came men in hither to night of the children of Israel to search out the country. And the king of Jericho sent unto Rahab, saying, Bring forth the men that are come to thee, which are entered into thine house: for they be come to search out all the country. And the woman took the two men, and hid them, and said thus, There came men unto me, but I wist not whence they were: And it came to pass about the time of shutting of the gate, when it was …') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-david','whoami',9,16,23,23,'1 Samuel 16:23',1,'Who am I?','["I was the youngest son of Jesse.", "I played the harp for King Saul.", "I defeated Goliath.", "I became king over Israel."]'::jsonb,'["Saul", "Jonathan", "David", "Solomon"]'::jsonb,2,'David took an harp and played, so Saul was refreshed.','Look in 1 Samuel.',null,null,'KJV',array['david','1 Samuel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And it came to pass, when the evil spirit from God was upon Saul, that David took an harp, and played with his hand: so Saul was refreshed, and was well, and the evil spirit departed from him.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-saul','whoami',9,9,2,2,'1 Samuel 9:2',2,'Who am I?','["I was of the tribe of Benjamin.", "From my shoulders upward I was higher than any of the people.", "Samuel anointed me as Israel''s first king.", "I consulted a woman at Endor."]'::jsonb,'["Absalom", "Jonathan", "David", "Saul"]'::jsonb,3,'Saul was "higher than any of the people" from his shoulders upward.','Look in 1 Samuel.',null,null,'KJV',array['saul','1 Samuel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And he had a son, whose name was Saul, a choice young man, and a goodly: and there was not among the children of Israel a goodlier person than he: from his shoulders and upward he was higher than any of the people.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-solomon','whoami',11,3,10,12,'1 Kings 3:10-12',1,'Who am I?','["My mother was Bathsheba.", "I asked God for an understanding heart.", "I built the temple in Jerusalem.", "I judged between two women who both claimed one baby."]'::jsonb,'["David", "Rehoboam", "Solomon", "Hezekiah"]'::jsonb,2,'God gave Solomon "a wise and an understanding heart."','Look in 1 Kings.',null,null,'KJV',array['solomon','1 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And the speech pleased the Lord, that Solomon had asked this thing. And God said unto him, Because thou hast asked this thing, and hast not asked for thyself long life; neither hast asked riches for thyself, nor hast asked the life of thine enemies; but hast asked for thyself understanding to discern judgment; Behold, I have done according to thy words: lo, I have given thee a wise and an understanding heart; so that there was none like thee before thee, neither after thee shall any arise like unto thee.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-elijah','whoami',11,17,1,6,'1 Kings 17:1-6',2,'Who am I?','["I was a Tishbite.", "Ravens fed me by the brook Cherith.", "I challenged the prophets of Baal on Mount Carmel.", "I went up by a whirlwind into heaven."]'::jsonb,'["Jonah", "Elisha", "Elijah", "Amos"]'::jsonb,2,'Ravens brought Elijah bread and flesh morning and evening.','Look in 1 Kings.',null,null,'KJV',array['elijah','1 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And Elijah the Tishbite, who was of the inhabitants of Gilead, said unto Ahab, As the LORD God of Israel liveth, before whom I stand, there shall not be dew nor rain these years, but according to my word. And the word of the LORD came unto him, saying, Get thee hence, and turn thee eastward, and hide thyself by the brook Cherith, that is before Jordan. And it shall be, that thou shalt drink of the brook; and I have commanded the ravens to feed thee there. So he went and did according unto the word of the LORD: for he went and dwelt by the brook Cherith, that is before Jordan. And the ravens brought him bread and flesh in the morning, and bread and flesh in the evening; and he drank of the …') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-daniel','whoami',27,6,23,23,'Daniel 6:23',1,'Who am I?','["I was taken captive to Babylon as a young man.", "I purposed not to defile myself with the king''s meat.", "I read the writing on the wall.", "I was delivered from the den of lions."]'::jsonb,'["Nehemiah", "Ezekiel", "Daniel", "Jeremiah"]'::jsonb,2,'Daniel was taken up out of the den, and no manner of hurt was found upon him.','Look in the Major Prophets.',null,null,'KJV',array['daniel','Daniel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'Then was the king exceeding glad for him, and commanded that they should take Daniel up out of the den. So Daniel was taken up out of the den, and no manner of hurt was found upon him, because he believed in his God.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-esther','whoami',17,4,16,16,'Esther 4:16',1,'Who am I?','["I was raised by my cousin Mordecai.", "I became queen in Persia.", "I said: If I perish, I perish.", "The feast of Purim remembers my people''s deliverance."]'::jsonb,'["Deborah", "Esther", "Vashti", "Ruth"]'::jsonb,1,'Esther resolved to go in unto the king, "and if I perish, I perish."','Look in the books of history.',null,null,'KJV',array['esther','Esther']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'Go, gather together all the Jews that are present in Shushan, and fast ye for me, and neither eat nor drink three days, night or day: I also and my maidens will fast likewise; and so will I go in unto the king, which is not according to the law: and if I perish, I perish.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-nehemiah','whoami',16,6,15,15,'Nehemiah 6:15',3,'Who am I?','["I was cupbearer to King Artaxerxes.", "I wept over Jerusalem''s broken walls.", "I led the rebuilding of the city wall.", "The wall was finished in fifty-two days."]'::jsonb,'["Nehemiah", "Ezra", "Zerubbabel", "Haggai"]'::jsonb,0,'"So the wall was finished... in fifty and two days."','Look in the books of history.',null,null,'KJV',array['nehemiah','Nehemiah']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'So the wall was finished in the twenty and fifth day of the month Elul, in fifty and two days.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-jonah','whoami',32,1,1,1,'Jonah 1:1',1,'Who am I?','["I was a prophet, the son of Amittai.", "I fled from God''s call on a ship.", "I spent three days inside a great fish.", "I was displeased when Nineveh repented."]'::jsonb,'["Nahum", "Hosea", "Amos", "Jonah"]'::jsonb,3,'The word of the LORD came unto Jonah the son of Amittai.','Look in the Minor Prophets.',null,null,'KJV',array['jonah','Jonah']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'Now the word of the LORD came unto Jonah the son of Amittai, saying,') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-isaiah','whoami',23,6,8,8,'Isaiah 6:8',2,'Who am I?','["I saw the Lord high and lifted up in the year King Uzziah died.", "A seraph touched my lips with a live coal.", "I answered: Here am I; send me.", "I prophesied of a child called Immanuel."]'::jsonb,'["Jeremiah", "Isaiah", "Micah", "Ezekiel"]'::jsonb,1,'Isaiah 6:8: "Here am I; send me."','Look in the Major Prophets.',null,null,'KJV',array['isaiah','Isaiah']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'Also I heard the voice of the Lord, saying, Whom shall I send, and who will go for us? Then said I, Here am I; send me.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-jeremiah','whoami',24,1,5,6,'Jeremiah 1:5-6',3,'Who am I?','["God said He knew me before He formed me in the belly.", "I protested that I was only a child.", "I was let down into a dungeon full of mire.", "Baruch wrote my words on a roll."]'::jsonb,'["Jeremiah", "Daniel", "Isaiah", "Ezekiel"]'::jsonb,0,'God told Jeremiah, "Before I formed thee in the belly I knew thee." Tradition calls him the weeping prophet.','Look in the Major Prophets.',null,null,'KJV',array['jeremiah','Jeremiah']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'Before I formed thee in the belly I knew thee; and before thou camest forth out of the womb I sanctified thee, and I ordained thee a prophet unto the nations. Then said I, Ah, Lord GOD! behold, I cannot speak: for I am a child.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-mary','whoami',42,1,26,27,'Luke 1:26-27',1,'Who am I?','["I lived in Nazareth of Galilee.", "The angel Gabriel was sent to me.", "I was espoused to Joseph.", "I gave birth to Jesus in Bethlehem."]'::jsonb,'["Elisabeth", "Martha", "Anna", "Mary"]'::jsonb,3,'Gabriel was sent to a virgin espoused to Joseph, and her name was Mary.','Look in Luke.',null,null,'KJV',array['mary','Luke']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And in the sixth month the angel Gabriel was sent from God unto a city of Galilee, named Nazareth, To a virgin espoused to a man whose name was Joseph, of the house of David; and the virgin’s name was Mary.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-john_baptist','whoami',40,3,4,4,'Matthew 3:4',1,'Who am I?','["My father Zacharias was a priest.", "I wore raiment of camel''s hair.", "I ate locusts and wild honey.", "I baptized Jesus in the Jordan."]'::jsonb,'["Peter", "Andrew", "John the Baptist", "Elijah"]'::jsonb,2,'John had raiment of camel''s hair and his meat was locusts and wild honey.','Look in Matthew.',null,null,'KJV',array['john_baptist','Matthew']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And the same John had his raiment of camel’s hair, and a leathern girdle about his loins; and his meat was locusts and wild honey.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-peter','whoami',40,26,75,75,'Matthew 26:75',1,'Who am I?','["I was a fisherman, the brother of Andrew.", "Jesus called me to become a fisher of men.", "I walked on the water toward Jesus.", "I denied Jesus three times before the cock crew."]'::jsonb,'["Peter", "John", "Andrew", "Thomas"]'::jsonb,0,'Peter remembered Jesus'' words, "Before the cock crow, thou shalt deny me thrice."','Look in Matthew.',null,null,'KJV',array['peter','Matthew']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And Peter remembered the word of Jesus, which said unto him, Before the cock crow, thou shalt deny me thrice. And he went out, and wept bitterly.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-thomas','whoami',43,20,28,28,'John 20:28',2,'Who am I?','["I was one of the twelve, called Didymus.", "I was absent when Jesus first appeared to the disciples.", "I wanted to see the print of the nails.", "I said: My Lord and my God."]'::jsonb,'["Thomas", "Philip", "Bartholomew", "Matthew"]'::jsonb,0,'Thomas answered and said unto him, "My Lord and my God."','Look in John.',null,null,'KJV',array['thomas','John']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And Thomas answered and said unto him, My Lord and my God.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-zacchaeus','whoami',42,19,2,4,'Luke 19:2-4',1,'Who am I?','["I was chief among the publicans.", "I was rich.", "I was little of stature.", "I climbed a sycomore tree to see Jesus."]'::jsonb,'["Zacchaeus", "Matthew", "Bartimaeus", "Nicodemus"]'::jsonb,0,'Zacchaeus climbed up into a sycomore tree to see Jesus.','Look in Luke.',null,null,'KJV',array['zacchaeus','Luke']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And, behold, there was a man named Zacchæus, which was the chief among the publicans, and he was rich. And he sought to see Jesus who he was; and could not for the press, because he was little of stature. And he ran before, and climbed up into a sycomore tree to see him: for he was to pass that way.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-nicodemus','whoami',43,3,1,3,'John 3:1-3',2,'Who am I?','["I was a Pharisee and a ruler of the Jews.", "I came to Jesus by night.", "Jesus told me I must be born again.", "I brought myrrh and aloes for Jesus'' burial."]'::jsonb,'["Joseph of Arimathaea", "Gamaliel", "Zacchaeus", "Nicodemus"]'::jsonb,3,'Jesus told Nicodemus, "Except a man be born again, he cannot see the kingdom of God."','Look in John.',null,null,'KJV',array['nicodemus','John']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'There was a man of the Pharisees, named Nicodemus, a ruler of the Jews: The same came to Jesus by night, and said unto him, Rabbi, we know that thou art a teacher come from God: for no man can do these miracles that thou doest, except God be with him. Jesus answered and said unto him, Verily, verily, I say unto thee, Except a man be born again, he cannot see the kingdom of God.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-lazarus','whoami',43,11,43,44,'John 11:43-44',1,'Who am I?','["I lived in Bethany.", "My sisters were Mary and Martha.", "Jesus wept near my grave.", "Jesus called me out of the tomb."]'::jsonb,'["Bartimaeus", "Simon", "Jairus", "Lazarus"]'::jsonb,3,'Jesus cried with a loud voice, "Lazarus, come forth."','Look in John.',null,null,'KJV',array['lazarus','John']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And when he thus had spoken, he cried with a loud voice, Lazarus, come forth. And he that was dead came forth, bound hand and foot with graveclothes: and his face was bound about with a napkin. Jesus saith unto them, Loose him, and let him go.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-martha','whoami',42,10,38,41,'Luke 10:38-41',3,'Who am I?','["I lived in Bethany with my sister and brother.", "I was cumbered about much serving.", "Jesus said my sister had chosen the good part.", "I welcomed Jesus into my house."]'::jsonb,'["Martha", "Mary Magdalene", "Salome", "Joanna"]'::jsonb,0,'"Martha was cumbered about much serving."','Look in Luke.',null,null,'KJV',array['martha','Luke']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'Now it came to pass, as they went, that he entered into a certain village: and a certain woman named Martha received him into her house. And she had a sister called Mary, which also sat at Jesus’ feet, and heard his word. But Martha was cumbered about much serving, and came to him, and said, Lord, dost thou not care that my sister hath left me to serve alone? bid her therefore that she help me. And Jesus answered and said unto her, Martha, Martha, thou art careful and troubled about many things:') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-paul','whoami',44,9,3,4,'Acts 9:3-4',1,'Who am I?','["I was born in Tarsus.", "I once persecuted the church.", "A light from heaven blinded me near Damascus.", "I wrote many letters to the churches."]'::jsonb,'["Barnabas", "Stephen", "Silas", "Paul"]'::jsonb,3,'Near Damascus a voice said, "Saul, Saul, why persecutest thou me?" He is later called Paul.','Look in Acts.',null,null,'KJV',array['paul','Acts']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And as he journeyed, he came near Damascus: and suddenly there shined round about him a light from heaven: And he fell to the earth, and heard a voice saying unto him, Saul, Saul, why persecutest thou me?') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-stephen','whoami',44,7,58,59,'Acts 7:58-59',2,'Who am I?','["I was one of seven chosen to serve the church.", "I was full of faith and power.", "As I spoke I saw the heavens opened.", "I was stoned while a young man named Saul watched."]'::jsonb,'["Barnabas", "Stephen", "James", "Philip"]'::jsonb,1,'The witnesses laid their clothes at Saul''s feet, and they stoned Stephen.','Look in Acts.',null,null,'KJV',array['stephen','Acts']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And cast him out of the city, and stoned him: and the witnesses laid down their clothes at a young man’s feet, whose name was Saul. And they stoned Stephen, calling upon God, and saying, Lord Jesus, receive my spirit.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-barnabas','whoami',44,4,36,37,'Acts 4:36-37',3,'Who am I?','["My name is interpreted ''the son of consolation''.", "I sold land and laid the money at the apostles'' feet.", "I brought Saul to the apostles in Jerusalem.", "I travelled with Paul on his first missionary journey."]'::jsonb,'["Timothy", "Barnabas", "Mark", "Silas"]'::jsonb,1,'Joses was surnamed Barnabas, "the son of consolation."','Look in Acts.',null,null,'KJV',array['barnabas','Acts']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And Joses, who by the apostles was surnamed Barnabas, (which is, being interpreted, The son of consolation,) a Levite, and of the country of Cyprus, Having land, sold it, and brought the money, and laid it at the apostles’ feet.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-lydia','whoami',44,16,14,15,'Acts 16:14-15',3,'Who am I?','["I was a seller of purple.", "I came from the city of Thyatira.", "I heard Paul speak by a riverside at Philippi.", "My household was baptized."]'::jsonb,'["Dorcas", "Priscilla", "Lydia", "Phebe"]'::jsonb,2,'Lydia, a seller of purple, of the city of Thyatira, heard Paul.','Look in Acts.',null,null,'KJV',array['lydia','Acts']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And a certain woman named Lydia, a seller of purple, of the city of Thyatira, which worshipped God, heard us: whose heart the Lord opened, that she attended unto the things which were spoken of Paul. And when she was baptized, and her household, she besought us, saying, If ye have judged me to be faithful to the Lord, come into my house, and abide there. And she constrained us.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-timothy','whoami',55,1,2,5,'2 Timothy 1:2-5',3,'Who am I?','["My grandmother Lois and mother Eunice shared unfeigned faith.", "I was Paul''s young companion.", "Paul called me his dearly beloved son.", "Two New Testament letters are addressed to me."]'::jsonb,'["Silas", "Titus", "Timothy", "Luke"]'::jsonb,2,'Paul remembered the faith in Lois and Eunice, and in Timothy.','Look in Paul''s letters.',null,null,'KJV',array['timothy','2 Timothy']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'To Timothy, my dearly beloved son: Grace, mercy, and peace, from God the Father and Christ Jesus our Lord. I thank God, whom I serve from my forefathers with pure conscience, that without ceasing I have remembrance of thee in my prayers night and day; Greatly desiring to see thee, being mindful of thy tears, that I may be filled with joy; When I call to remembrance the unfeigned faith that is in thee, which dwelt first in thy grandmother Lois, and thy mother Eunice; and I am persuaded that in thee also.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-adam','whoami',1,2,19,20,'Genesis 2:19-20',1,'Who am I?','["I was formed of the dust of the ground.", "I gave names to the animals.", "I lived in the garden of Eden.", "My wife was Eve."]'::jsonb,'["Enoch", "Cain", "Seth", "Adam"]'::jsonb,3,'"Adam gave names to all cattle, and to the fowl of the air."','Look in Genesis.',null,null,'KJV',array['adam','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And out of the ground the LORD God formed every beast of the field, and every fowl of the air; and brought them unto Adam to see what he would call them: and whatsoever Adam called every living creature, that was the name thereof. And Adam gave names to all cattle, and to the fowl of the air, and to every beast of the field; but for Adam there was not found an help meet for him.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-cain','whoami',1,4,9,9,'Genesis 4:9',2,'Who am I?','["I was a tiller of the ground.", "God did not respect my offering.", "I asked: Am I my brother''s keeper?", "God set a mark upon me."]'::jsonb,'["Abel", "Seth", "Cain", "Lamech"]'::jsonb,2,'Cain answered, "I know not: Am I my brother''s keeper?"','Look in Genesis.',null,null,'KJV',array['cain','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And the LORD said unto Cain, Where is Abel thy brother? And he said, I know not: Am I my brother’s keeper?') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-methuselah','whoami',1,5,27,27,'Genesis 5:27',4,'Who am I?','["My father was Enoch.", "My son was Lamech.", "I was Noah''s grandfather.", "I lived nine hundred sixty and nine years."]'::jsonb,'["Methuselah", "Mahalaleel", "Jared", "Enoch"]'::jsonb,0,'"All the days of Methuselah were nine hundred sixty and nine years."','Look in Genesis.',null,null,'KJV',array['methuselah','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And all the days of Methuselah were nine hundred sixty and nine years: and he died.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-enoch','whoami',1,5,24,24,'Genesis 5:24',3,'Who am I?','["I walked with God.", "I was the father of Methuselah.", "I was not, for God took me.", "Hebrews says I was translated so I should not see death."]'::jsonb,'["Elijah", "Noah", "Enoch", "Seth"]'::jsonb,2,'"Enoch walked with God: and he was not; for God took him."','Look in Genesis.',null,null,'KJV',array['enoch','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And Enoch walked with God: and he was not; for God took him.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-melchizedek','whoami',1,14,18,20,'Genesis 14:18-20',4,'Who am I?','["I was king of Salem.", "I was priest of the most high God.", "I brought forth bread and wine to Abram.", "Abram gave me tithes of all."]'::jsonb,'["Abimelech", "Melchizedek", "Aaron", "Jethro"]'::jsonb,1,'Melchizedek king of Salem brought forth bread and wine.','Look in Genesis.',null,null,'KJV',array['melchizedek','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And Melchizedek king of Salem brought forth bread and wine: and he was the priest of the most high God. And he blessed him, and said, Blessed be Abram of the most high God, possessor of heaven and earth: And blessed be the most high God, which hath delivered thine enemies into thy hand. And he gave him tithes of all.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-hannah','whoami',9,1,13,20,'1 Samuel 1:13-20',2,'Who am I?','["My husband was Elkanah.", "I prayed silently at Shiloh, and Eli thought I was drunk.", "I vowed to give my son to the LORD.", "I named my son Samuel."]'::jsonb,'["Sarah", "Elisabeth", "Peninnah", "Hannah"]'::jsonb,3,'Hannah bore a son and called his name Samuel.','Look in 1 Samuel.',null,null,'KJV',array['hannah','1 Samuel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'Now Hannah, she spake in her heart; only her lips moved, but her voice was not heard: therefore Eli thought she had been drunken. And Eli said unto her, How long wilt thou be drunken? put away thy wine from thee. And Hannah answered and said, No, my lord, I am a woman of a sorrowful spirit: I have drunk neither wine nor strong drink, but have poured out my soul before the LORD. Count not thine handmaid for a daughter of Belial: for out of the abundance of my complaint and grief have I spoken hitherto. Then Eli answered and said, Go in peace: and the God of Israel grant thee thy petition that thou hast asked of him. And she said, Let thine handmaid find grace in thy sight. So the woman went …') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-job','whoami',18,1,21,21,'Job 1:21',1,'Who am I?','["I lived in the land of Uz.", "I was perfect and upright.", "I lost my children and possessions in a single day.", "I said: The LORD gave, and the LORD hath taken away."]'::jsonb,'["Bildad", "Job", "Elihu", "Eliphaz"]'::jsonb,1,'"The LORD gave, and the LORD hath taken away; blessed be the name of the LORD."','Look in the books of poetry and wisdom.',null,null,'KJV',array['job','Job']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And said, Naked came I out of my mother’s womb, and naked shall I return thither: the LORD gave, and the LORD hath taken away; blessed be the name of the LORD.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-naaman','whoami',12,5,14,14,'2 Kings 5:14',3,'Who am I?','["I was captain of the host of the king of Syria.", "I was a leper.", "A captive little maid from Israel told of a prophet.", "I dipped myself seven times in the Jordan."]'::jsonb,'["Ben-hadad", "Hazael", "Naaman", "Gehazi"]'::jsonb,2,'He dipped himself seven times in Jordan and his flesh came again.','Look in 2 Kings.',null,null,'KJV',array['naaman','2 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'Then went he down, and dipped himself seven times in Jordan, according to the saying of the man of God: and his flesh came again like unto the flesh of a little child, and he was clean.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-caleb','whoami',6,14,6,13,'Joshua 14:6-13',4,'Who am I?','["I was one of the twelve spies.", "I brought back a good report with Joshua.", "I was eighty-five years old when I asked for my inheritance.", "I asked for the mountain and received Hebron."]'::jsonb,'["Othniel", "Joshua", "Caleb", "Phinehas"]'::jsonb,2,'Joshua blessed Caleb and gave him Hebron for an inheritance.','Look in the books of history.',null,null,'KJV',array['caleb','Joshua']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'Then the children of Judah came unto Joshua in Gilgal: and Caleb the son of Jephunneh the Kenezite said unto him, Thou knowest the thing that the LORD said unto Moses the man of God concerning me and thee in Kadesh-barnea. Forty years old was I when Moses the servant of the LORD sent me from Kadesh-barnea to espy out the land; and I brought him word again as it was in mine heart. Nevertheless my brethren that went up with me made the heart of the people melt: but I wholly followed the LORD my God. And Moses sware on that day, saying, Surely the land whereon thy feet have trodden shall be thine inheritance, and thy children’s for ever, because thou hast wholly followed the LORD my God. And …') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-matthew','whoami',40,9,9,9,'Matthew 9:9',2,'Who am I?','["I was a publican.", "I sat at the receipt of custom.", "Jesus said to me: Follow me.", "Jesus ate with publicans and sinners at my table."]'::jsonb,'["Simon", "Judas", "Matthew", "Zacchaeus"]'::jsonb,2,'Jesus saw a man named Matthew sitting at the receipt of custom.','Look in the Gospels.',null,null,'KJV',array['matthew','Matthew']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And as Jesus passed forth from thence, he saw a man, named Matthew, sitting at the receipt of custom: and he saith unto him, Follow me. And he arose, and followed him.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-judas','whoami',40,26,14,15,'Matthew 26:14-15',1,'Who am I?','["I was one of the twelve.", "I had the bag.", "I agreed to betray Jesus for thirty pieces of silver.", "I betrayed Jesus with a kiss."]'::jsonb,'["Peter", "Thomas", "Judas Iscariot", "Andrew"]'::jsonb,2,'Judas Iscariot covenanted with the chief priests for thirty pieces of silver.','Look in Matthew.',null,null,'KJV',array['judas','Matthew']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'Then one of the twelve, called Judas Iscariot, went unto the chief priests, And said unto them, What will ye give me, and I will deliver him unto you? And they covenanted with him for thirty pieces of silver.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-mary_magdalene','whoami',43,20,15,16,'John 20:15-16',2,'Who am I?','["Seven devils had gone out of me.", "I stood by the cross.", "I came to the tomb while it was yet dark.", "At first I supposed the risen Jesus was the gardener."]'::jsonb,'["Martha", "Mary the mother of James", "Mary Magdalene", "Salome"]'::jsonb,2,'She, supposing him to be the gardener... Jesus saith unto her, Mary.','Look in John.',null,null,'KJV',array['mary_magdalene','John']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'Jesus saith unto her, Woman, why weepest thou? whom seekest thou? She, supposing him to be the gardener, saith unto him, Sir, if thou have borne him hence, tell me where thou hast laid him, and I will take him away. Jesus saith unto her, Mary. She turned herself, and saith unto him, Rabboni; which is to say, Master.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-john_apostle','whoami',66,1,9,9,'Revelation 1:9',2,'Who am I?','["I was a son of Zebedee.", "Jesus surnamed my brother and me Boanerges.", "Tradition identifies me as the disciple whom Jesus loved.", "I was on the isle of Patmos for the word of God."]'::jsonb,'["Andrew", "John", "Philip", "James"]'::jsonb,1,'"I John... was in the isle that is called Patmos." Identifying the Revelation author with the apostle is traditional.','Look in Revelation.',null,null,'KJV',array['john_apostle','Revelation']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'I John, who also am your brother, and companion in tribulation, and in the kingdom and patience of Jesus Christ, was in the isle that is called Patmos, for the word of God, and for the testimony of Jesus Christ.') on conflict (id) do nothing;
