insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-nathan','whoami',10,12,7,7,'2 Samuel 12:7',3,'Who am I?','["I was a prophet in David''s court.", "I told David his son would build God''s house.", "I told David a parable about a poor man''s ewe lamb.", "I said to David, Thou art the man."]'::jsonb,'["Samuel", "Gad", "Ahijah", "Nathan"]'::jsonb,3,'Nathan said to David, "Thou art the man."','Look in the books of history.',null,null,'KJV',array['nathan','2 Samuel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And Nathan said to David, Thou art the man. Thus saith the LORD God of Israel, I anointed thee king over Israel, and I delivered thee out of the hand of Saul;') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-absalom','whoami',10,18,9,9,'2 Samuel 18:9',3,'Who am I?','["I was a son of King David.", "I stole the hearts of the men of Israel.", "I led a rebellion against my father.", "My head caught in an oak as my mule went on."]'::jsonb,'["Amnon", "Absalom", "Adonijah", "Solomon"]'::jsonb,1,'Absalom''s mule went under the thick boughs of a great oak, and his head caught hold of the oak.','Look in 2 Samuel.',null,null,'KJV',array['absalom','2 Samuel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And Absalom met the servants of David. And Absalom rode upon a mule, and the mule went under the thick boughs of a great oak, and his head caught hold of the oak, and he was taken up between the heaven and the earth; and the mule that was under him went away.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-jezebel','whoami',11,19,2,2,'1 Kings 19:2',2,'Who am I?','["I was the daughter of the king of the Zidonians.", "I was the wife of King Ahab.", "I threatened Elijah''s life after Mount Carmel.", "I arranged Naboth''s death to take his vineyard."]'::jsonb,'["Delilah", "Jezebel", "Vashti", "Athaliah"]'::jsonb,1,'Jezebel sent a messenger unto Elijah, threatening his life.','Look in 1 Kings.',null,null,'KJV',array['jezebel','1 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Then Jezebel sent a messenger unto Elijah, saying, So let the gods do to me, and more also, if I make not thy life as the life of one of them by to morrow about this time.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-ahab','whoami',11,21,2,2,'1 Kings 21:2',2,'Who am I?','["I was a king of Israel.", "I married Jezebel.", "I asked Elijah, Art thou he that troubleth Israel?", "I wanted Naboth''s vineyard for a garden of herbs."]'::jsonb,'["Ahab", "Jeroboam", "Omri", "Jehu"]'::jsonb,0,'Ahab said to Naboth, "Give me thy vineyard."','Look in 1 Kings.',null,null,'KJV',array['ahab','1 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And Ahab spake unto Naboth, saying, Give me thy vineyard, that I may have it for a garden of herbs, because it is near unto my house: and I will give thee for it a better vineyard than it; or, if it seem good to thee, I will give thee the worth of it in money.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-hezekiah','whoami',23,38,5,5,'Isaiah 38:5',3,'Who am I?','["I was a king of Judah.", "I broke in pieces the brasen serpent that Moses had made.", "Isaiah told me to set my house in order.", "God added fifteen years to my life."]'::jsonb,'["Hezekiah", "Josiah", "Manasseh", "Uzziah"]'::jsonb,0,'God said through Isaiah, "I will add unto thy days fifteen years."','Look in Isaiah.',null,null,'KJV',array['hezekiah','Isaiah']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Go, and say to Hezekiah, Thus saith the LORD, the God of David thy father, I have heard thy prayer, I have seen thy tears: behold, I will add unto thy days fifteen years.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-josiah','whoami',12,22,1,1,'2 Kings 22:1',4,'Who am I?','["I became king of Judah at eight years old.", "The book of the law was found in the temple in my reign.", "I rent my clothes when it was read to me.", "I kept a great passover."]'::jsonb,'["Joash", "Josiah", "Hezekiah", "Jehoiakim"]'::jsonb,1,'"Josiah was eight years old when he began to reign."','Look in 2 Kings.',null,null,'KJV',array['josiah','2 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Josiah was eight years old when he began to reign, and he reigned thirty and one years in Jerusalem. And his mother’s name was Jedidah, the daughter of Adaiah of Boscath.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-ezra','whoami',16,8,4,4,'Nehemiah 8:4',3,'Who am I?','["I was a priest and a ready scribe in the law of Moses.", "I went up from Babylon in the reign of Artaxerxes.", "I read the book of the law to the people.", "I stood upon a pulpit of wood."]'::jsonb,'["Ezra", "Zerubbabel", "Nehemiah", "Haggai"]'::jsonb,0,'Ezra the scribe stood upon a pulpit of wood.','Look in the books of history.',null,null,'KJV',array['ezra','Nehemiah']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And Ezra the scribe stood upon a pulpit of wood, which they had made for the purpose; and beside him stood Mattithiah, and Shema, and Anaiah, and Urijah, and Hilkiah, and Maaseiah, on his right hand; and on his left hand, Pedaiah, and Mishael, and Malchiah, and Hashum, and Hashbadana, Zechariah, and Meshullam.') on conflict (id) do nothing;
