insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-elisabeth','whoami',42,1,41,41,'Luke 1:41',2,'Who am I?','["I was of the daughters of Aaron.", "I was barren and well stricken in years.", "My babe leaped in my womb when Mary greeted me.", "I was the mother of John the Baptist."]'::jsonb,'["Elisabeth", "Anna", "Salome", "Mary"]'::jsonb,0,'When Elisabeth heard Mary''s greeting, the babe leaped in her womb.','Look in Luke.',null,null,'KJV',array['elisabeth','Luke']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And it came to pass, that, when Elisabeth heard the salutation of Mary, the babe leaped in her womb; and Elisabeth was filled with the Holy Ghost:') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-simeon','whoami',42,2,29,29,'Luke 2:29',3,'Who am I?','["I was a just and devout man in Jerusalem.", "The Holy Ghost revealed I would not die before seeing the Lord''s Christ.", "I took the child Jesus up in my arms in the temple.", "I said: Lord, now lettest thou thy servant depart in peace."]'::jsonb,'["Simeon", "Joseph of Arimathaea", "Zacharias", "Nicodemus"]'::jsonb,0,'Simeon said, "Lord, now lettest thou thy servant depart in peace, according to thy word."','Look in Luke.',null,null,'KJV',array['simeon','Luke']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Lord, now lettest thou thy servant depart in peace, according to thy word:') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-anna','whoami',42,2,36,36,'Luke 2:36',3,'Who am I?','["I was a prophetess of the tribe of Aser.", "I was a widow of about fourscore and four years.", "I served God with fastings and prayers night and day.", "I gave thanks when the child Jesus was brought to the temple."]'::jsonb,'["Elisabeth", "Anna", "Phebe", "Dorcas"]'::jsonb,1,'"There was one Anna, a prophetess... of the tribe of Aser."','Look in Luke.',null,null,'KJV',array['anna','Luke']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And there was one Anna, a prophetess, the daughter of Phanuel, of the tribe of Aser: she was of a great age, and had lived with an husband seven years from her virginity;') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-joseph_husband','whoami',40,1,20,20,'Matthew 1:20',2,'Who am I?','["I was of the house and lineage of David.", "An angel told me in a dream not to fear to take Mary as my wife.", "I took the young child and his mother into Egypt by night.", "People called Jesus the carpenter''s son."]'::jsonb,'["Joseph of Arimathaea", "Zacharias", "Simeon", "Joseph, husband of Mary"]'::jsonb,3,'The angel said, "Joseph, thou son of David, fear not to take unto thee Mary thy wife."','Look in Matthew.',null,null,'KJV',array['joseph_husband','Matthew']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'But while he thought on these things, behold, the angel of the Lord appeared unto him in a dream, saying, Joseph, thou son of David, fear not to take unto thee Mary thy wife: for that which is conceived in her is of the Holy Ghost.') on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text) values ('who-andrew','whoami',43,1,40,42,'John 1:40-42',2,'Who am I?','["I was from Bethsaida.", "I was one of two who heard John the Baptist speak and followed Jesus.", "I brought my brother Simon to Jesus.", "I told Jesus of a lad with five barley loaves."]'::jsonb,'["James", "Andrew", "Nathanael", "Philip"]'::jsonb,1,'Andrew first found his own brother Simon and brought him to Jesus.','Look in John.',null,null,'KJV',array['andrew','John']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'One of the two which heard John speak, and followed him, was Andrew, Simon Peter’s brother. He first findeth his own brother Simon, and saith unto him, We have found the Messias, which is, being interpreted, the Christ. And he brought him to Jesus. And when Jesus beheld him, he said, Thou art Simon the son of Jona: thou shalt be called Cephas, which is by interpretation, A stone.') on conflict (id) do nothing;
